import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

// `grade` is the grade in force on the sheet's today; `grades` every grade they were given with the date it
// applies from (null for the first, which applies from the beginning of time), by from-date.
// `version` is raised on every save; an edit sends the version it loaded and is refused (409) when
// someone else has saved the person since.
// `statementCount` is how many statements were taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and the sheet's today when it was taken (null with none).
// `retiredFrom` is the date they are retired from (null: not retired); with one set they count as retired at
// once, whatever the date.
// `held`: their OPEN claims count in no live total; their SETTLED claims still count.
// `patronIds`: the other people on the sheet they have named as patrons, in the order they were named.
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: DatedGrade[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
  patronIds: number[];
};

/** A grade a person was given, from a date on (YYYY-MM-DD; null: from the beginning of time). */
export type DatedGrade = { grade: string; from: string | null };

/** The grade in force for a person on a date: the one whose from-date is the latest on or before it, the first
 *  grade they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found = person.grade;
  for (const g of person.grades) {
    if (g.from === null || g.from <= date) found = g.grade;
  }
  return found;
}

export const peopleQueryKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peoplePath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleQueryKey(sheet ?? ''),
    queryFn: () => getJson<Person[]>(peoplePath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open (search param `editPerson`), or '' for none. */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether retired people are listed (search param `showRetired`): off when the screen is first opened, and
 *  left as it is by loading a sheet. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, useEditingPerson, useShowRetired } from './people';

// The sheet's people in the order they were added — retired people only while show-retired is on — each with their name, grade in force on the sheet's today and an edit button;
// features add their own columns through PeopleColumns / PersonCells.
function PeopleList() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople();
  const [showRetired] = useShowRetired();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <th />
          <PeopleColumns.Slot />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).filter((p) => showRetired || p.retiredFrom === null).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>{p.name}</td>
            <td data-testid="person-grade">{gradeOn(p, today)}</td>
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(String(p.id))}>
                Edit
              </button>
            </td>
            <PersonCells.Slot person={p} />
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export const contribution = HomeMain.fill({ order: 20, Component: PeopleList });
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useShowRetired } from './people';

// The show-retired toggle above the people list: off, retired people have no row at all.
function ShowRetiredToggle() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [showRetired, setShowRetired] = useShowRetired();
  if (!user || !sheet) return null;
  return (
    <label>
      <input
        type="checkbox"
        data-testid="show-retired"
        checked={showRetired}
        onChange={(e) => setShowRetired(e.target.checked || undefined)}
      />{' '}
      Show retired
    </label>
  );
}

export const contribution = HomeMain.fill({ order: 18, Component: ShowRetiredToggle });
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, heldIds, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, rateOn, sumDue, useRates, type Rate } from './rates';

// A person's due-total: the sum of their counted claims' dues, each already rounded (a settled claim's
// frozen due, else the figure their last statement bound it to, else its live due, at least the sheet's floor; plus
// an overdue claim's late charge; each claim at the grade they had on its date) — 0.00 with nothing that counts.
// When their grade in force on the sheet's today has no rate in force then it is n/a, unless a counted claim keeps
// a figure — settled, bound, or live at another grade they had on its date: then it is the sum of the figures there are. While they are held their OPEN claims do not count. The sheet's due-total is everyone's added up, skipping n/a.
export function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, heldIds([person])));
  const grade = gradeOn(person, today);
  const kept = (c: Claim) => c.due !== null || (c.stated && c.statedDue !== null)
    || (!c.stated && gradeOn(person, c.date) !== grade && chargedOf(c, rates, gradeOn(person, c.date), settings, today) !== 'n/a');
  if (rateOn(rates, grade, today) === undefined && !mine.some(kept)) {
    return 'n/a';
  }
  return sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}

function DueHeader() {
  return <th>Due</th>;
}

function PersonDue({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-due-total">{personDue(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const total = sumDue((people.data ?? []).map((p) => personDue(p, claims.data ?? [], rates.data, today, settings.data)));
  return (
    <p>
      Due in total <strong data-testid="rollup-due-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15, Component: DueHeader }),
  PersonCells.fill({ order: 15, Component: PersonDue }),
  HomeMain.fill({ order: 31, Component: DueTotal }),
];
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { peoplePath, peopleQueryKey, type Person } from './people';

// Whether a person is on hold, and the button that puts them on hold or takes them off it. While held, their
// OPEN claims count in no live total; their SETTLED claims still count.
function HoldHeader() {
  return <th>Hold</th>;
}

function PersonHold({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  const hold = useMutation({
    mutationFn: (body: { held: boolean }) => putJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/hold`, body, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') }),
  });
  const submit = useSubmitOnce(hold);
  return (
    <td>
      <span data-testid="person-hold">{person.held ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-hold-toggle"
        disabled={hold.isPending}
        onClick={() => submit({ held: !person.held })}
      >
        {person.held ? 'Release' : 'Hold'}
      </button>
      {hold.isError && <span data-testid="person-error">The hold could not be changed.</span>}
    </td>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 45, Component: HoldHeader }),
  PersonCells.fill({ order: 45, Component: PersonHold }),
];
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/**
 * The shell's session bar: who is signed in and which sheet is active. Its contributions own the
 * `user` and `sheet` search params (read anywhere with url/useSearchParam).
 */
export const AppSession = defineSlot('app.session');
import { defineSlot } from '../Slot';

/** The home page's body: every panel on the one screen at `/` contributes itself here. */
export const HomeMain = defineSlot('home.main');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** The people table's extra column headers: each contributes one or more `<th>`. */
export const PeopleColumns = defineSlot('people.columns');

/**
 * The people table's extra cells for one person's row, in the same order as PeopleColumns: each
 * contributes `<td>`s. Everything inside a person's row belongs to `person-row-<id>`.
 */
export const PersonCells = defineSlot<{ person: Person }>('people.cells');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}

